function parsePath(d) {
  const tok = d.match(/[MCZ]|-?\d*\.?\d+/g);
  const segs = []; let i = 0, cur = null;
  while (i < tok.length) {
    const t = tok[i++];
    if (t === 'M') { cur = [+tok[i++], +tok[i++]]; }
    else if (t === 'C') {
      const a = [+tok[i++], +tok[i++]], b = [+tok[i++], +tok[i++]], c = [+tok[i++], +tok[i++]];
      segs.push([cur, a, b, c]); cur = c;
    }
  }
  return segs;
}
