  const nearest = (x, y) => { let b = 0, bd = Infinity; for (let s = 0; s < npt; s++) { const d = (out[2 * s] - x) ** 2 + (out[2 * s + 1] - y) ** 2; if (d < bd) { bd = d; b = s; } } return b; };
  const iTip = nearest(1172, 2628), iCusp = nearest(1893, 1977);
  const topEdge = iCusp > iTip ? out.slice(2 * iTip, 2 * iCusp + 2) : out.slice(2 * iTip).concat(out.slice(0, 2 * iCusp + 2));
  const ft = distanceField(topEdge, null, W, H, cell, 0, 0);
  // spine: front (body) side is below the curve; keel: front side is to the right of travel
  const sp = flatten(parsePath(DATA.paths.spine), 3.0);
  const fs = distanceField(sp, null, W, H, cell, 0, 0);
  const inS = fillMask(sp.concat([-1300, 9000, 6400, 9000]), W, H, cell, 0, 0);
  const kl = flatten(parsePath(DATA.paths.keel), 3.0);
  const fk = distanceField(kl, null, W, H, cell, 0, 0);
  const inK = fillMask(kl.concat([9000, 5000, 9000, -3200, -1500, -3200]), W, H, cell, 0, 0);
