    dS[q] = inO[q] ? -fo.dist[q] : fo.dist[q];
    dSp[q] = inS[q] ? fs.dist[q] : -fs.dist[q];
    dK[q] = inK[q] ? fk.dist[q] : -fk.dist[q];
    tex[4 * q] = dS[q]; tex[4 * q + 1] = dSp[q]; tex[4 * q + 2] = dK[q]; tex[4 * q + 3] = Math.min(ft.dist[q], 3000);
